WITH flattened AS (SELECT id, level, latency_ms, status_code, k, value FROM app_logs LATERAL VIEW EXPLODE(context) e AS k, value) SELECT id, level, latency_ms, status_code, k, value, COUNT(status_code) OVER w_grp AS last7_count_status_code, MAX(status_code) OVER w_grp AS last7_max_status_code, SUM(status_code) OVER w_grp AS last7_sum_status_code, FIRST_VALUE(latency_ms) IGNORE NULLS OVER w_running AS first_known_latency_ms FROM flattened WINDOW w_grp AS (PARTITION BY k ORDER BY status_code, id, k ROWS BETWEEN 6 PRECEDING AND CURRENT ROW), w_running AS (ORDER BY status_code, id, k ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);
